import React, { cloneElement, Ref } from 'react';
import { useProgressTrackerContext } from '../../ProgressTrackerContext';
import { ProgressTrackerHeaderProps } from './ProgressTrackerHeader.types';
import { StyledProgressTrackerHeaderContainer } from './ProgressTrackerHeader.styles';

const ProgressTrackerHeader = React.forwardRef(
  ({ children }: ProgressTrackerHeaderProps, forwardedRef: Ref<HTMLUListElement>): JSX.Element => {
    const steps = React.Children.map(
      children as React.ReactElement[],
      (child: React.ReactElement, index: number) =>
        cloneElement(child, {
          index,
          ...child.props,
        })
    );

    const progressTrackerContext = useProgressTrackerContext();
    if (!progressTrackerContext) {
      // eslint-disable-next-line no-console
      console.warn(
        'Make sure of ProgressTracker.Header component is subcomponent of ProgressTracker.Root.'
      );
      return <></>;
    }

    const { orientation, size } = progressTrackerContext;

    return (
      <StyledProgressTrackerHeaderContainer
        ref={forwardedRef}
        orientation={orientation}
        size={size}
      >
        {steps}
      </StyledProgressTrackerHeaderContainer>
    );
  }
);

export default ProgressTrackerHeader;
